class TestDgLexer(unittest.TestCase):
    def test_dg_operator(self):
        lexer = DgLexer()
        tokens = list(lexer.get_tokens('|>'))
        self.assertEqual(tokens[0], (Token.Operator, '|>'))

    def test_dg_builtin(self):
        lexer = DgLexer()
        tokens = list(lexer.get_tokens('map'))
        self.assertEqual(tokens[0], (Token.Name.Builtin, 'map'))

class TestNumPyLexer(unittest.TestCase):
    def test_numpy_keyword(self):
        lexer = NumPyLexer()
        tokens = list(lexer.get_tokens('array'))
        self.assertEqual(tokens[0], (Token.Keyword.Pseudo, 'array'))

    def test_analyse_text_with_numpy_import(self):
        result = NumPyLexer.analyse_text('import numpy as np\nnp.array([1,2,3])')
        self.assertTrue(result)

    def test_analyse_text_without_numpy(self):
        result = NumPyLexer.analyse_text('import sys\nsys.exit()')
        self.assertFalse(result)

class TestLexerEdgeCases(unittest.TestCase):
    def test_python_lexer_with_unicode_identifier(self):
        lexer = PythonLexer()
        tokens = list(lexer.get_tokens('var = 1'))
        self.assertEqual(tokens[0], (Token.Name, 'var'))

    def test_string_with_escape(self):
        lexer = PythonLexer()
        tokens = list(lexer.get_tokens('"line1\\nline2"'))
        self.assertEqual(tokens[0][1], '"line1\\nline2"')

    def test_mixed_operators(self):
        lexer = PythonLexer()
        tokens = list(lexer.get_tokens('x += 1'))
        self.assertEqual(tokens[1], (Token.Operator, '+='))

    def test_multiline_statement(self):
        lexer = PythonLexer()
        tokens = list(self.lexer.get_tokens('x = 1 + \\\n2'))
        self.assertIn((Token.Text, '\\\n'), tokens)

    def test_docstring(self):
        lexer = PythonLexer()
        tokens = list(self.lexer.get_tokens('def foo():\n    """doc"""'))
        self.assertEqual(tokens[4], (Token.String.Doc, '"""doc"""'))

if __name__ == '__main__':
    unittest.main()
